"""Generate plain Django code (view, url, template) from a block."""
import io
import pprint
import zipfile

from django.template import Context, Engine

# We are writing Python, not HTML, so autoescaping must be off (Engine and Context).
ENGINE = Engine(autoescape=False)

VIEWS_PY = '''from django.contrib.auth.mixins import PermissionRequiredMixin
from django.views.generic import ListView

from {{ app_label }}.models import {{ model_name }}


class {{ class_name }}(PermissionRequiredMixin, ListView):
    """Generated by KOD Data Viewer from the block "{{ block_name }}"."""

    model = {{ model_name }}
    permission_required = "{{ perm }}"
    template_name = "{{ template_path }}"
    paginate_by = {{ cfg.pagination }}
    fields = {{ fields_repr }}

    def get_queryset(self):
        qs = super().get_queryset(){% if related %}.select_related({{ related_repr }}){% endif %}
        filters = {{ filters_repr }}
        return qs.filter(**filters).order_by({{ ordering_repr }})
'''

URLS_PY = '''from django.urls import path

from .views import {{ class_name }}

urlpatterns = [
    path("{{ slug }}/", {{ class_name }}.as_view(), name="{{ slug_underscore }}"),
]
'''

TEMPLATE_HTML = '''{% templatetag openblock %} extends "base.html" {% templatetag closeblock %}

{% templatetag openblock %} block content {% templatetag closeblock %}
<h1 class="h3 mb-3">{{ block_name }}</h1>
<div class="table-responsive">
  <table class="table table-striped table-hover align-middle">
    <thead>
      <tr>{% for f in cfg.fields %}<th>{{ f }}</th>{% endfor %}</tr>
    </thead>
    <tbody>
    {% templatetag openblock %} for obj in object_list {% templatetag closeblock %}
      <tr>{% for f in cfg.fields %}<td>{% templatetag openvariable %} obj.{{ f }} {% templatetag closevariable %}</td>{% endfor %}</tr>
    {% templatetag openblock %} empty {% templatetag closeblock %}
      <tr><td colspan="{{ cfg.fields|length }}" class="text-muted">Nothing here yet.</td></tr>
    {% templatetag openblock %} endfor {% templatetag closeblock %}
    </tbody>
  </table>
</div>
{% templatetag openblock %} if is_paginated {% templatetag closeblock %}
<nav>
  {% templatetag openblock %} if page_obj.has_previous {% templatetag closeblock %}<a class="btn btn-outline-secondary btn-sm" href="?page={% templatetag openvariable %} page_obj.previous_page_number {% templatetag closevariable %}">Previous</a>{% templatetag openblock %} endif {% templatetag closeblock %}
  <span class="mx-2">Page {% templatetag openvariable %} page_obj.number {% templatetag closevariable %} of {% templatetag openvariable %} page_obj.paginator.num_pages {% templatetag closevariable %}</span>
  {% templatetag openblock %} if page_obj.has_next {% templatetag closeblock %}<a class="btn btn-outline-secondary btn-sm" href="?page={% templatetag openvariable %} page_obj.next_page_number {% templatetag closevariable %}">Next</a>{% templatetag openblock %} endif {% templatetag closeblock %}
</nav>
{% templatetag openblock %} endif {% templatetag closeblock %}
{% templatetag openblock %} endblock {% templatetag closeblock %}
'''

README_MD = '''# {{ block_name }}

Generated by KOD Data Viewer.

* Source model: `{{ source_key }}` (already exists, so no models are generated)
* Fields: {{ cfg.fields|join:", " }}
* Filters: `{{ filters_repr }}`
* Ordering: `{{ ordering }}`
* Page size: {{ cfg.pagination }}

## Install

1. Copy `views.py` content into your app's `views.py` (or keep it as a separate module).
2. Add the pattern from `urls.py` to your app's urls.
3. Copy `templates/{{ template_path }}` into your templates folder.
4. Users need the `{{ perm }}` permission.
'''


def build_context(block, source):
    cfg = block.config
    meta = source.model._meta
    slug = "".join(c if c.isalnum() else "-" for c in block.name.lower()).strip("-") or "block"
    class_name = "".join(part.capitalize() for part in slug.split("-") if part) + "ListView"
    if not class_name[0].isalpha():
        class_name = "Block" + class_name
    related = [f for f in cfg.get("fields", []) if source.field(f).many_to_one or source.field(f).one_to_one]
    ordering = cfg.get("ordering") or "-pk"
    return {
        "block_name": block.name.replace('"', "'"),
        "source_key": source.key,
        "app_label": meta.app_label,
        "model_name": meta.object_name,
        "perm": source.view_perm,
        "class_name": class_name,
        "slug": slug,
        "slug_underscore": slug.replace("-", "_"),
        "template_path": f"{meta.app_label}/{slug.replace('-', '_')}.html",
        "cfg": cfg,
        "fields_repr": pprint.pformat(cfg.get("fields", [])),
        "filters_repr": pprint.pformat(cfg.get("filters", {})),
        "related": related,
        "related_repr": ", ".join(repr(r) for r in related),
        "ordering": ordering,
        "ordering_repr": repr(ordering),
    }


def render(source_text, context):
    return ENGINE.from_string(source_text).render(Context(context, autoescape=False))


def generate_files(block, source):
    ctx = build_context(block, source)
    return {
        "views.py": render(VIEWS_PY, ctx),
        "urls.py": render(URLS_PY, ctx),
        f"templates/{ctx['template_path']}": render(TEMPLATE_HTML, ctx),
        "README.md": render(README_MD, ctx),
    }


def build_zip(block, source):
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as zf:
        for path, content in generate_files(block, source).items():
            zf.writestr(path, content)
    return buffer.getvalue()
